import{describe,it,expect}from"vitest";import{CONSTITUENT_ASSEMBLY_MEMBERS,DRAFTING_TIMELINE_STEPS,filterMembers,getAssemblyStats}from"../../frontend/constitution-makers/constitution-makers.js";describe("Constituent Assembly Members Dataset Integrity",()=>{it("contains featured key members including Dr. B. R. Ambedkar, Rajendra Prasad, Nehru, Patel, and Hansa Mehta",()=>{const e=CONSTITUENT_ASSEMBLY_MEMBERS.map(e=>e.id);expect(e).toContain("ambedkar"),expect(e).toContain("rajendra-prasad"),expect(e).toContain("nehru"),expect(e).toContain("patel"),expect(e).toContain("hansa-mehta"),expect(e).toContain("dakshayani"),expect(e).toContain("begum-aizaz-rasul")}),it("every member entry includes required fields (name, role, committee, contributions, biography, portrait)",()=>{CONSTITUENT_ASSEMBLY_MEMBERS.forEach((e,t)=>{expect(e,`Member at index ${t} missing id`).toHaveProperty("id"),expect(e,`Member at index ${t} missing name`).toHaveProperty("name"),expect(e,`Member at index ${t} missing role`).toHaveProperty("role"),expect(e,`Member at index ${t} missing committee`).toHaveProperty("committee"),expect(e,`Member at index ${t} missing contributions`).toHaveProperty("contributions"),expect(e,`Member at index ${t} missing biography`).toHaveProperty("biography"),expect(e,`Member at index ${t} missing portrait`).toHaveProperty("portrait"),expect(typeof e.name).toBe("string"),expect(e.name.trim().length).toBeGreaterThan(0),expect(typeof e.contributions).toBe("string"),expect(e.contributions.trim().length).toBeGreaterThan(0)})}),it("contains women pioneers of the Assembly",()=>{const e=CONSTITUENT_ASSEMBLY_MEMBERS.filter(e=>e.isWomanMember);expect(e.length).toBeGreaterThanOrEqual(4);const t=e.map(e=>e.name);expect(t).toContain("Hansa Jivraj Mehta"),expect(t).toContain("Begum Aizaz Rasul"),expect(t).toContain("Dakshayani Velayudhan")}),it("maintains non-partisan, objective, and educational tone",()=>{const e=["corrupt","worthless","unlawful","fraudulent"];CONSTITUENT_ASSEMBLY_MEMBERS.forEach(t=>{const a=`${t.name} ${t.role} ${t.contributions} ${t.biography}`.toLowerCase();e.forEach(e=>{expect(a).not.toContain(e)})})})}),describe("Constitution Drafting Timeline Integrity",()=>{it("contains key milestones from Dec 9, 1946 to Jan 26, 1950",()=>{expect(DRAFTING_TIMELINE_STEPS.length).toBeGreaterThanOrEqual(8),expect(DRAFTING_TIMELINE_STEPS[0].date).toContain("December 9, 1946"),expect(DRAFTING_TIMELINE_STEPS[DRAFTING_TIMELINE_STEPS.length-1].date).toContain("January 26, 1950")}),it("every timeline step contains date, phase, title, and details",()=>{DRAFTING_TIMELINE_STEPS.forEach((e,t)=>{expect(e,`Timeline step at index ${t} missing date`).toHaveProperty("date"),expect(e,`Timeline step at index ${t} missing phase`).toHaveProperty("phase"),expect(e,`Timeline step at index ${t} missing title`).toHaveProperty("title"),expect(e,`Timeline step at index ${t} missing details`).toHaveProperty("details")})})}),describe("Constituent Assembly Helper Functions",()=>{it("filters members by committee correctly",()=>{const e=filterMembers(CONSTITUENT_ASSEMBLY_MEMBERS,"Drafting Committee","");expect(e.length).toBeGreaterThan(0);const t=filterMembers(CONSTITUENT_ASSEMBLY_MEMBERS,"women","");expect(t.length).toBeGreaterThanOrEqual(4),t.forEach(e=>expect(e.isWomanMember).toBe(!0))}),it("searches members by keyword query",()=>{const e=filterMembers(CONSTITUENT_ASSEMBLY_MEMBERS,"all","Ambedkar");expect(e.length).toBe(1),expect(e[0].name).toContain("Ambedkar");const t=filterMembers(CONSTITUENT_ASSEMBLY_MEMBERS,"all","Hansa");expect(t.length).toBe(1),expect(t[0].name).toContain("Hansa")}),it("calculates valid assembly stats summary",()=>{const e=getAssemblyStats(CONSTITUENT_ASSEMBLY_MEMBERS);expect(e.totalFeaturedMembers).toBeGreaterThanOrEqual(10),expect(e.womenMembersCount).toBeGreaterThanOrEqual(4),expect(e.totalOriginalMembers).toBe(299)})});